import{_ as e,o as t,c as o,ah as r}from"./chunks/framework.BdHuibk5.js";const _=JSON.parse('{"title":"金华写志","description":"“水通南国三千里，气压江城十四州”，从地理形胜、历史沿革、人文风物到双龙洞胜景，写一座物华天宝、人杰地灵的金华。","frontmatter":{"title":"金华写志","date":"2009-10-18 01:45","category":"prose","tags":["金华","城市","人文"],"slug":"jinhua-notes","layout":"blog-post","description":"“水通南国三千里，气压江城十四州”，从地理形胜、历史沿革、人文风物到双龙洞胜景，写一座物华天宝、人杰地灵的金华。"},"headers":[],"relativePath":"blog/jinhua-notes.md","filePath":"blog/posts/prose/jinhua-notes.md","lastUpdated":1789447662000}'),s={name:"blog/jinhua-notes.md"};function n(i,a,l,p,h,d){return t(),o("div",null,[...a[0]||(a[0]=[r('<h2 id="金华概貌" tabindex="-1">金华概貌 <a class="header-anchor" href="#金华概貌" aria-label="Permalink to &quot;金华概貌&quot;">​</a></h2><p>“水通南国三千里，气压江城十四州”，著名女词人李清照的诗句生动概括了金华的重要位置和雄伟气势。金华市位于浙江省的中部，为省辖地级市，界于东经119゜14′ -120゜46′30″，北纬28゜32′-29゜41′，南北跨度129公里，东西跨度151公里，土地面积10918平方公里，2001年末人口447.94万人，其中市区91.34万人。为亚热带季风气候，四季分明。</p><p>金华的市树为樟树，市花为山茶花。</p><h2 id="历史沿革" tabindex="-1">历史沿革 <a class="header-anchor" href="#历史沿革" aria-label="Permalink to &quot;历史沿革&quot;">​</a></h2><p>金华建制久远，古属越国地，秦入会稽郡，三国吴宝鼎元年（266年）置郡始名东阳，历名金华、婺州，或设郡、州、路、府，或设道、区、专区和地区，1985年5月，国务院批准撤消金华地区，分设金华、衢州两市，实行市辖县体制。2000年12月31日，国务院批准撤消金华县，并将其与原婺城区辖区作了调整，设立金东区。现金华市下辖婺城、金东2区及兰溪、义乌、东阳、永康4市和武义、浦江、磐安3县。</p><h2 id="人文风物" tabindex="-1">人文风物 <a class="header-anchor" href="#人文风物" aria-label="Permalink to &quot;人文风物&quot;">​</a></h2><p>金华素有“小邹鲁”之称，历来为文化礼仪之邦，历史上讲学群起，书院迭兴。宋元时期金华学派与金华文派名播四海。当今则基础教育、高等教育、成人教育三头并兴。文化兴盛必然名人辈出。文坛巨匠、丹青大师、爱国志士、民族英雄、专家学者，金华土地上代不乏人。如“初唐四杰”之一的骆宾王、“诗名画皆奇绝”的五代诗僧和书画家贯休、宋代抗金名将宗泽、南宋“浙东学派”代表人物吕祖谦、陈亮，金元四大名医之一的朱丹溪，明朝“开国文臣之首”的宋濂，清代戏曲家、戏曲理论家李渔，近现代有国画大师黄宾虹、一代报人邵飘萍、史学家吴晗、诗人潘漠华、艾青及文学批评家冯雪峰，杰出科学家严济慈、蔡希陶等，他们彪炳史册，光照千秋，为后人留下了宝贵的精神财富。崇文重教的风气沿袭至今，形成了如今金华“千名教授汇一市，百名博士集一乡”的盛况。</p><p>金华的山水和人文旅游资源十分丰富。金华山川秀丽奇绝，国家级风景区双龙洞早已蜚声中外，省级风景区永康方岩、兰溪六洞山地下长河、浦江仙华山、武义郭洞-龙潭、磐安花溪、东阳花都-屏岩、汤溪九峰山等，或为山奇，或为水秀，可谓各擅胜场。金华的文物古迹与奇山秀水交相辉映，有国家级文保单位10处，省级文保单位37处，县（市）级文保单位300多处，馆藏文物达3万多件。各处古迹遗址如颗颗明珠，点缀于八婺大地。太平天国侍王府、宋代名刹天宁寺、八咏楼、五峰书院等胜迹及诸葛八卦村、俞源太极村等神秘村落以及东阳卢宅等令游客流连忘返。传统与现代交融、人称东方好莱坞的横店影视城也已成为广大影视工作者和游客心中的福地。古婺风情多姿多彩，斗牛、道情、龙灯、浦江抬阁、永康《十八蝴蝶》、磐安龙虎大旗等民俗风情各具特色，引人入胜。</p><p>金华传统名优特产有金华火腿、东阳木雕、义乌南枣、金丝蜜枣、金华佛手、宣平莲子等。它们有的曾被列为贡品，有的多次在国内外博览会上获奖。</p><p>金华物华天宝、人杰地灵。金华人民立足深厚的传统文明与文化，并正以自己的智慧与勤奋创造崭新的历史。</p><h2 id="双龙洞" tabindex="-1">双龙洞 <a class="header-anchor" href="#双龙洞" aria-label="Permalink to &quot;双龙洞&quot;">​</a></h2><p>双龙洞位于距金华市区15公里处的北山风景区，被誉为“水石奇观”。分内洞与外洞两个部分，外洞面积约1200平方米，侗高约66米，常年温度为摄氏15℃左右。进入洞口的岩壁上，镌有宋代书法家吴琳手书“洞天”二字，洞口两侧的崖壁上悬挂着一对状如龙头的钟乳石。虽然龙头在外洞，但龙身却在内洞。双龙洞的内外洞之间有一块巨大的岩石覆盖于清泉之上，水道宽丈余，水面与岩顶仅留一尺左右空隙，游人进入洞内，必须平卧于船底，仰面从岩下穿引而入。当行至岩底之中，面部与岩石仅隔二、三寸，稍一抬头，就有擦破鼻额的危险，大有岩石沉沉欲坠、压身的感觉。内洞略大于外洞，岩洞深遂，约2000多平方米。在小船上岸处，仰望洞顶，即见黄龙、青龙翻腾干空，一条青色钟乳岩纹自东北洞顶婉蜒而至；另有一条黄色钟乳石自西北俯冲而来，龙须、龙爪、龙身、龙鳞、龙尾等清晰可辨，形象栩栩如生。洞内钟乳石、石笋比比皆是，奇形怪状，拟人似物，有“寿星仙桃”、“黄龙吐水”、“天鹅仰首”、“金鹞展翅”、“雄狮迈步”、“单峰骆驼”、“石蛙窥穴”、“龟蛇共生”、“彩云遮月”；还有“石鼓”、“宝剑”、“晴雨石”等等，使人目不暇接、眼花缭乱，身临其境，犹如一座水晶宫。北山风景区，素有“五洞十景”之观，除双龙洞外，尚有冰壶洞、朝真洞、讲堂洞、罗汉洞、芙蓉峰、鹿田庄、智者寺等，可供游人观赏揽胜。</p>',12)])])}const u=e(s,[["render",n]]);export{_ as __pageData,u as default};
